import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {EdgeDatabaseService,EdgeOutboxPersistence} from '../tridentpos/packages/edge/dist/index.js';
import {createPosFastifyApp} from '../tridentpos/packages/pos-edge-runtime/dist/index.js';
const dir=fs.mkdtempSync(path.join(os.tmpdir(),'review65-'));
const db=new EdgeDatabaseService({databasePath:path.join(dir,'db.sqlite')});
const outbox=new EdgeOutboxPersistence(db);
let calls=0;
const pinValidator={validatePin:async()=>{calls++;return false;}};
const appA=await createPosFastifyApp({edgeDb:db,outbox,organizationId:'ORG_A',branchId:'BR_A',stationId:'ST_A',pinValidator});
const appB=await createPosFastifyApp({edgeDb:db,outbox,organizationId:'ORG_B',branchId:'BR_B',stationId:'ST_B',pinValidator});
const request=async(app,url,payload)=>{const r=await app.inject({method:'POST',url,payload});return {status:r.statusCode,body:r.json()};};
const opened=await request(appB,'/turnos/apertura',{responsibleUserId:'OP',openingCashFloat:'100.0000'});
assert.equal(opened.status,201);
const id=opened.body.turno.id;
const denied=await request(appB,`/turnos/${id}/movimientos`,{operatorUserId:'OP',operatorPin:'wrong',movementType:'VENTA_EFECTIVO',amount:'1.0000',reason:'test',expectedVersion:1});
assert.equal(denied.status,401);
const countBefore=calls;
const bypass=await request(appB,`/turnos/${id}/movimientos`,{operatorUserId:'OP',movementType:'VENTA_EFECTIVO',amount:'1.0000',reason:'test',expectedVersion:1});
assert.equal(bypass.status,201);assert.equal(calls,countBefore);
console.log(JSON.stringify({probe:'PIN omitted',explicitInvalidStatus:denied.status,omittedStatus:bypass.status,validatorCallsDuringOmitted:calls-countBefore}));
const foreign=await request(appA,`/turnos/${id}/movimientos`,{operatorUserId:'OP',movementType:'VENTA_EFECTIVO',amount:'2.0000',reason:'cross tenant',expectedVersion:2});
assert.equal(foreign.status,201);assert.equal(foreign.body.turno.organizationId,'ORG_B');
console.log(JSON.stringify({probe:'foreign stored aggregate',enrolled:'ORG_A/BR_A/ST_A',actualStatus:foreign.status,mutatedTenant:foreign.body.turno.organizationId,mutatedStation:foreign.body.turno.stationId,version:foreign.body.turno.version}));
const mismatch=await request(appA,'/turnos/apertura',{organizationId:'OTHER',responsibleUserId:'OP',openingCashFloat:'0.0000'});
assert.equal(mismatch.status,403);assert.match(mismatch.body.message,/ORG_A/);
console.log(JSON.stringify({probe:'tenant identity disclosure',...mismatch}));
const noStation=await createPosFastifyApp({edgeDb:db,outbox,organizationId:'ORG_A',branchId:'BR_A',pinValidator});
const arbitrary=await request(noStation,'/turnos/apertura',{stationId:'CLIENT_CHOSEN',responsibleUserId:'OP',openingCashFloat:'0.0000'});
assert.equal(arbitrary.status,201);assert.equal(arbitrary.body.turno.stationId,'CLIENT_CHOSEN');
console.log(JSON.stringify({probe:'station from request without enrollment',status:arbitrary.status,station:arbitrary.body.turno.stationId}));
const nonParticipant=await request(appB,`/turnos/${id}/corte-x`,{requestedByUserId:'STRANGER'});
assert.equal(nonParticipant.status,403);
console.log(JSON.stringify({probe:'non participant',status:nonParticipant.status,error:nonParticipant.body.error}));
await Promise.all([appA.close(),appB.close(),noStation.close()]);db.close();fs.rmSync(dir,{recursive:true,force:true});

